#include "opensim/scene/movement.hpp"
#include <bit>
#include <iomanip>
#include <iostream>
using namespace opensim;using namespace scene;
int main(int argc,char** argv){try{if(argc>1&&std::string(argv[1])=="--probe"){int seed,mode;while(std::cin>>seed>>mode){MovementState s;s.rotation={seed*.01f,-.2f,.3f,.4f};s.flying=mode&1;s.npc=mode&2;s.moving_to_target=mode&4;s.colliding=mode&8;s.falling=mode&16;s.has_physics_actor=mode&32;s.pid_hover_active=mode&64;s.controls=mode&512?0x10:0;s.speed_modifier=seed*.125f;s.move_to_speed=mode&1024?3.125f:-1.f;s.delayed_stop=1234;framework::Vector3 v{seed*.25f,-.5f,mode&256?0.f:.75f};if(mode&2048)v={};add_new_movement(s,v,seed*.03125f+.25f,mode&128);for(auto x:{s.target_velocity.x,s.target_velocity.y,s.target_velocity.z})std::cout<<std::hex<<std::bit_cast<std::uint32_t>(x)<<',';std::cout<<std::dec<<s.delayed_stop<<','<<s.animation_updates<<','<<std::hex<<remove_ignored_controls(0xaabbccddu^static_cast<std::uint32_t>(seed),static_cast<std::uint32_t>(mode));auto c=project_controls(static_cast<std::uint32_t>(seed)*0x12345u^static_cast<std::uint32_t>(mode),static_cast<std::uint32_t>(mode)>>3,(mode&1)!=0,seed>=0?1u:0u);std::cout<<'/';for(auto x:{c.relative.x,c.relative.y,c.relative.z,c.speed})std::cout<<std::hex<<std::bit_cast<std::uint32_t>(x)<<',';std::cout<<c.controls<<','<<c.movement_flags<<','<<int(c.changed)<<','<<int(c.key_pressed)<<'\n';}return 0;}
 MovementState state;add_new_movement(state,{1,0,0},2.4576f);if(state.target_velocity!=framework::Vector3{2.4576f,0,0}||state.delayed_stop!=-1||state.animation_updates!=1)throw std::runtime_error("Ground movement projection");state.flying=true;state.colliding=true;add_new_movement(state,{1,0,-1},1);if(state.target_velocity!=framework::Vector3{})throw std::runtime_error("Flying landing suppression");state.falling=true;state.pid_hover_active=false;add_new_movement(state,{},1,true);if(state.target_velocity.z!=-9999.f)throw std::runtime_error("Source falling brake sentinel");std::cout<<"PASS: source movement projection\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
